package com.clavis.reader;
import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.widget.ImageView;import java.util.*;
/** White paper behind publisher artwork; a readable publisher badge is always present offline. */
final class FeedIcons {
 static ImageView tile(MainActivity a,String title){ImageView image=new ImageView(a);GradientDrawable paper=new GradientDrawable();paper.setColor(Color.WHITE);paper.setCornerRadius(a.dp(10));paper.setStroke(a.dp(1),0xffdedede);image.setBackground(paper);image.setClipToOutline(true);image.setPadding(a.dp(6),a.dp(6),a.dp(6),a.dp(6));image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setImageBitmap(badge(title));return image;}
 static Bitmap badge(String title){Bitmap bitmap=Bitmap.createBitmap(160,160,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(Color.WHITE);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setColor(0xff292664);paint.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));String label=label(title);String[] lines=label.split("\n");paint.setTextSize(lines.length>1?34:42);float widest=0;for(String line:lines)widest=Math.max(widest,paint.measureText(line));if(widest>140)paint.setTextSize(paint.getTextSize()*140/widest);Paint.FontMetrics fm=paint.getFontMetrics();float spacing=paint.getTextSize()*1.2f,start=80-(fm.ascent+fm.descent)/2-(lines.length-1)*spacing/2;for(int n=0;n<lines.length;n++)canvas.drawText(lines[n],80-paint.measureText(lines[n])/2,start+n*spacing,paint);return bitmap;}
 static String label(String title){String name=title==null?"":title.trim(),lower=name.toLowerCase(Locale.ROOT);if(lower.contains("new england")||lower.equals("nejm"))return "NEJM";if(lower.contains("jama"))return "JAMA";if(lower.contains("lancet"))return "LANCET";if(lower.contains("bmj"))return lower.contains("open")?"BMJ\nOPEN":"BMJ";if(lower.contains("plos"))return "PLOS";if(lower.contains("clinical investigation"))return "JCI";if(lower.contains("annals of internal"))return "ANNALS";if(lower.equals("elife"))return "eLife";if(lower.equals("nature medicine"))return "NATURE\nMED";if(lower.contains("nature reviews"))return "NATURE\nREVIEWS";if(lower.contains("bbc"))return "BBC";if(lower.contains("npr"))return "NPR";if(lower.contains("new york times"))return "NYT";StringBuilder initials=new StringBuilder();for(String word:name.split("[^\\p{L}\\p{N}]+")){if(word.isEmpty()||word.equalsIgnoreCase("the")||word.equalsIgnoreCase("of")||word.equalsIgnoreCase("and"))continue;initials.appendCodePoint(Character.toUpperCase(word.codePointAt(0)));if(initials.length()>=4)break;}return initials.length()==0?"RSS":initials.toString();}
}
